/**
 * OWNED BY client-foundation agent.
 * Skin registry (loaded from /assets/skins/manifest.json, generated by scripts/build_assets.py)
 * + equipped cosmetics store (zustand, persisted in localStorage).
 *
 * Ids:
 *  - skinId:       manifest entry id ('default', 'classic-dark', 'fire', 'deco', ...)
 *  - backId:       'default' = follow the equipped skin's default back, otherwise a global back id
 *                  '<skinId>/<slug>' from `SkinManifestEntry.backs[].id` (e.g. 'fire/split-flame')
 *  - backgroundId: BackgroundEntry id ('default' = classic desk, or a skin id like 'fire')
 */
import { useEffect, useMemo } from 'react';
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { Card, Rank, Suit } from '@belot/engine';

export interface SuitIconEntry {
  path: string;
  /** English label of the custom symbol (e.g. 'Flame') */
  label: string;
  /** localized labels */
  labels?: { en: string; bg: string };
}

export interface SkinManifestEntry {
  id: string; // 'default' | 'fire' | ...
  name: string;
  /** localized display names */
  names?: { en: string; bg: string };
  basePath: string; // e.g. /assets/skins/default or /assets/skins/custom-skins/fire
  /** suit -> pip icon path + label of the custom symbol, for the suit-equivalence hint badge */
  suitIcons: Record<Suit, SuitIconEntry>;
  backs: { id: string; path: string; name?: string }[];
  defaultBack: string;
  background?: string; // matching desk background path
  /** id of the matching background in the backgrounds manifest */
  backgroundId?: string;
  /** preview card image (Ace of hearts) */
  preview?: string;
  priceEurCents: number; // 0 = free
}

export interface BackgroundEntry {
  id: string;
  path: string;
  width: number;
  height: number;
  name: { en: string; bg: string };
  /** skin this background is paired with */
  skinId: string;
  priceEurCents: number;
}

export const SKIN_MANIFEST_URL = '/assets/skins/manifest.json';
export const BACKGROUND_MANIFEST_URL = '/assets/backgrounds/manifest.json';

export const SUIT_FILE_NAME: Record<Suit, string> = { S: 'spades', H: 'hearts', D: 'diamonds', C: 'clubs' };
export const SUIT_SYMBOL: Record<Suit, string> = { S: '♠', H: '♥', D: '♦', C: '♣' };
export const SUIT_IS_RED: Record<Suit, boolean> = { S: false, H: true, D: true, C: false };
export const SUITS: Suit[] = ['S', 'H', 'D', 'C'];
export const RANKS: Rank[] = ['7', '8', '9', '10', 'J', 'Q', 'K', 'A'];

/** native sprite size of a card (px) */
export const CARD_WIDTH = 23;
export const CARD_HEIGHT = 35;

const DEFAULT_BASE = '/assets/skins/default';

/** Static fallback for the free default skin, usable before the manifest has loaded. */
export const DEFAULT_SKIN: SkinManifestEntry = {
  id: 'default',
  name: 'Classic',
  names: { en: 'Classic', bg: 'Класически' },
  basePath: DEFAULT_BASE,
  suitIcons: {
    H: { path: `${DEFAULT_BASE}/suit-icons/hearts.png`, label: 'Hearts', labels: { en: 'Hearts', bg: 'Купа' } },
    S: { path: `${DEFAULT_BASE}/suit-icons/spades.png`, label: 'Spades', labels: { en: 'Spades', bg: 'Пика' } },
    C: { path: `${DEFAULT_BASE}/suit-icons/clubs.png`, label: 'Clubs', labels: { en: 'Clubs', bg: 'Спатия' } },
    D: { path: `${DEFAULT_BASE}/suit-icons/diamonds.png`, label: 'Diamonds', labels: { en: 'Diamonds', bg: 'Каро' } },
  },
  backs: [{ id: 'default/light-classic', path: `${DEFAULT_BASE}/backs/light-classic.png`, name: 'LightClassic' }],
  defaultBack: 'default/light-classic',
  background: '/assets/backgrounds/default-desk.png',
  backgroundId: 'default',
  preview: `${DEFAULT_BASE}/cards/A_hearts.png`,
  priceEurCents: 0,
};

export const DEFAULT_BACKGROUND: BackgroundEntry = {
  id: 'default',
  path: '/assets/backgrounds/default-desk.png',
  width: 38,
  height: 38,
  name: { en: 'Classic Felt', bg: 'Класическо сукно' },
  skinId: 'default',
  priceEurCents: 0,
};

/* ------------------------------------------------------------------ path helpers */

export function cardImagePath(card: Card, skin: Pick<SkinManifestEntry, 'basePath'> = DEFAULT_SKIN): string {
  return `${skin.basePath}/cards/${card.rank}_${SUIT_FILE_NAME[card.suit]}.png`;
}

/** Resolve a back id ('default' = the skin's own default back) to an image path. */
export function resolveBackPath(skins: SkinManifestEntry[], skin: SkinManifestEntry, backId?: string): string {
  if (backId && backId !== 'default') {
    for (const s of skins) {
      const b = s.backs.find((x) => x.id === backId);
      if (b) return b.path;
    }
  }
  return skin.backs.find((b) => b.id === skin.defaultBack)?.path ?? `${skin.basePath}/cards/back.png`;
}

/* ------------------------------------------------------------------ manifest loading */

interface ManifestState {
  skins: SkinManifestEntry[];
  backgrounds: BackgroundEntry[];
  loaded: boolean;
  error: string | null;
}

const useManifestStore = create<ManifestState>(() => ({
  skins: [DEFAULT_SKIN],
  backgrounds: [DEFAULT_BACKGROUND],
  loaded: false,
  error: null,
}));

let loadPromise: Promise<SkinManifestEntry[]> | null = null;

/** Fetch both manifests once (cached). Resolves with the skin list. */
export function loadSkinManifest(): Promise<SkinManifestEntry[]> {
  if (!loadPromise) {
    loadPromise = Promise.all([
      fetch(SKIN_MANIFEST_URL).then((r) => {
        if (!r.ok) throw new Error(`skin manifest: HTTP ${r.status}`);
        return r.json() as Promise<SkinManifestEntry[]>;
      }),
      fetch(BACKGROUND_MANIFEST_URL)
        .then((r) => (r.ok ? (r.json() as Promise<BackgroundEntry[]>) : [DEFAULT_BACKGROUND]))
        .catch(() => [DEFAULT_BACKGROUND]),
    ])
      .then(([skins, backgrounds]) => {
        useManifestStore.setState({ skins, backgrounds, loaded: true, error: null });
        return skins;
      })
      .catch((e: unknown) => {
        loadPromise = null;
        useManifestStore.setState({ loaded: true, error: e instanceof Error ? e.message : String(e) });
        return useManifestStore.getState().skins;
      });
  }
  return loadPromise;
}

/** All skins from manifest.json (falls back to the default skin until loaded). */
export function useSkinManifest(): {
  skins: SkinManifestEntry[];
  backgrounds: BackgroundEntry[];
  loaded: boolean;
  error: string | null;
  getSkin: (id: string | undefined) => SkinManifestEntry;
  getBackground: (id: string | undefined) => BackgroundEntry;
} {
  const skins = useManifestStore((s) => s.skins);
  const backgrounds = useManifestStore((s) => s.backgrounds);
  const loaded = useManifestStore((s) => s.loaded);
  const error = useManifestStore((s) => s.error);
  useEffect(() => {
    if (!loaded) void loadSkinManifest();
  }, [loaded]);
  return useMemo(
    () => ({
      skins,
      backgrounds,
      loaded,
      error,
      getSkin: (id) => skins.find((s) => s.id === id) ?? skins.find((s) => s.id === 'default') ?? DEFAULT_SKIN,
      getBackground: (id) =>
        backgrounds.find((b) => b.id === id) ?? backgrounds.find((b) => b.id === 'default') ?? DEFAULT_BACKGROUND,
    }),
    [skins, backgrounds, loaded, error],
  );
}

/* ------------------------------------------------------------------ equipped cosmetics */

export interface EquippedCosmetics {
  skinId: string;
  backId: string;
  backgroundId: string;
}

interface CosmeticsState extends EquippedCosmetics {
  setSkin: (skinId: string) => void;
  setBack: (backId: string) => void;
  setBackground: (backgroundId: string) => void;
  /** equip a skin together with its matching back + background */
  equipSkinSet: (skin: SkinManifestEntry) => void;
  reset: () => void;
}

const DEFAULT_EQUIPPED: EquippedCosmetics = { skinId: 'default', backId: 'default', backgroundId: 'default' };

export const useCosmeticsStore = create<CosmeticsState>()(
  persist(
    (set) => ({
      ...DEFAULT_EQUIPPED,
      setSkin: (skinId) => set({ skinId }),
      setBack: (backId) => set({ backId }),
      setBackground: (backgroundId) => set({ backgroundId }),
      equipSkinSet: (skin) => set({ skinId: skin.id, backId: 'default', backgroundId: skin.backgroundId ?? 'default' }),
      reset: () => set(DEFAULT_EQUIPPED),
    }),
    {
      name: 'belot-cosmetics',
      version: 1,
      partialize: (s) => ({ skinId: s.skinId, backId: s.backId, backgroundId: s.backgroundId }),
    },
  ),
);

/** Currently equipped cosmetics (+ setters). */
export function useEquippedCosmetics(): EquippedCosmetics & {
  setSkin: (id: string) => void;
  setBack: (id: string) => void;
  setBackground: (id: string) => void;
  equipSkinSet: (skin: SkinManifestEntry) => void;
} {
  const skinId = useCosmeticsStore((s) => s.skinId);
  const backId = useCosmeticsStore((s) => s.backId);
  const backgroundId = useCosmeticsStore((s) => s.backgroundId);
  const setSkin = useCosmeticsStore((s) => s.setSkin);
  const setBack = useCosmeticsStore((s) => s.setBack);
  const setBackground = useCosmeticsStore((s) => s.setBackground);
  const equipSkinSet = useCosmeticsStore((s) => s.equipSkinSet);
  return { skinId, backId, backgroundId, setSkin, setBack, setBackground, equipSkinSet };
}

/* imperative setters (usable outside React) */
export const setEquippedSkin = (id: string) => useCosmeticsStore.getState().setSkin(id);
export const setEquippedBack = (id: string) => useCosmeticsStore.getState().setBack(id);
export const setEquippedBackground = (id: string) => useCosmeticsStore.getState().setBackground(id);
export const getEquippedCosmetics = (): EquippedCosmetics => {
  const { skinId, backId, backgroundId } = useCosmeticsStore.getState();
  return { skinId, backId, backgroundId };
};

/** The skin entry to render with (explicit id or the equipped one) + resolved back path. */
export function useActiveSkin(skinId?: string, backId?: string): { skin: SkinManifestEntry; backPath: string } {
  const eq = useEquippedCosmetics();
  const { skins, getSkin } = useSkinManifest();
  const skin = getSkin(skinId ?? eq.skinId);
  // an explicit skinId without an explicit back shows that skin's own default back
  const effectiveBack = backId ?? (skinId ? 'default' : eq.backId);
  return { skin, backPath: resolveBackPath(skins, skin, effectiveBack) };
}

/** The desk background to render (explicit id or the equipped one). */
export function useActiveBackground(backgroundId?: string): BackgroundEntry {
  const eq = useEquippedCosmetics();
  const { getBackground } = useSkinManifest();
  return getBackground(backgroundId ?? eq.backgroundId);
}

/** Localized helper: pick `names[lang]` falling back to `name`. */
export function skinDisplayName(skin: SkinManifestEntry, lang: string): string {
  return (lang === 'bg' ? skin.names?.bg : skin.names?.en) ?? skin.name;
}
